ee:message.ee:set-payload:
%dw 2.0
output application/json skipNullOn = "everywhere"
var zsmartResponse = payload.result.result
---
{
  codeResponse: "200",
  messageResponse: "OK",
  accounts: [
    {
      transactionID: zsmartResponse.transactionID,
      accountNumber: vars.billingAccount,
      balances: zsmartResponse.balDtoList map ((item, index) -> {
        balanceId: item.balID,
        balanceTypeCode: item.acctResCode,
        balanceTypeName: item.acctResName,
        balance: item.balance,
        effectiveDate: item.effDate,
        expirationDate: item.expDate,
        lastUpdateDate: item.updateDate
      })
    }
  ]
}

%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: p('mongo-db-sapi.resources.dynamicQuery.base-path'),
	body: {
		"query": {
			"aggregate": "MDM_CUENTA_FACTURACION",
			"pipeline": [{
				"\$match": {
					"Tipo_Documento": vars.billingParams.'CUSTOMER_ID_TYPE',
					"Numero_Identificacion": vars.billingParams.'CUSTOMER_ID'
				}
			}],
			"cursor": {
			}
		}
	},
	headers: vars.billingHeaders default {
	},
	queryParameters: {
	},
	uriParameters: {
	}
}

%dw 2.0
output application/json
---
{
  "WSRequestHeader": {
    "System": {
      "name": vars.headers.name,
      "correlationID": vars.headers."X-CORRELATION-ID",
      "processingServer": ""
    },
    "Property": []
  },
  "WSRequestBody": {
    "Audit": {
      "Canal": vars.headers.name
    },
    "Phone": (vars.parameters.CONNECTION_NUMBER default ""),
  }
}

%dw 2.0
output application/json
var response = payload
---
{
  codeResponse: vars.httpStatus as String ,
  messageResponse: if(payload.WSResponseHeader.Service.status == "OK") payload.WSResponseHeader.Service.statusDetail[0].errorDetailCode else payload.WSResponseHeader.Service.statusDetail[0].errorMessage,
  balance: {
    availableCoin: response.WSResponseBody.Available_Coin,
    availableCoinValue: response.WSResponseBody.Available_Coin_Value,
    promotionCoin: response.WSResponseBody.Promotion_Coin,
    promotionCoinValue: response.WSResponseBody.Promotion_Coin_Value,
    detailed: {
      detail: response.WSResponseBody.Detailed.Detail map (d) -> {
        sectionName: d.Section_Name,
        boxes: d.Boxs map (b) -> {
          boxName: b.Box_Name,
          groupName: b.Group_Name,
          unitType: b.Unity_Type,
          available: b.Available,
          consumed: b.Consume,
          provisioned: b.Provisioned,
          offers: b.Offers map (o) -> {
            offerName: o.Offer_Name,
            available: o.Available,
            consumed: o.Consumed,
            provisioned: o.Provisioned,
            expirationDate: o.Expiration_Date
          }
        }
      }
    },
    summary: {
      resource: response.WSResponseBody.Resume.Resource map (r) -> {
        name: r.Name,
        available: r.Available,
        consumed: r.Consumed,
        provisioned: r.Provisioned,
        expirationDate: r.Expiration_Date
      }
    }
  }
}
